package org.example

class App {

}
fun sleepQuality(hours: Double): String {
    return when {
        hours < 6 -> "Insufficient"
        hours <= 9 -> "Normal"
        else -> "Too much"
    }
}
data class SleepRecord(
    val name: String,
    val hours: Double
)
data class HealthRecord(
    val id: Int,
    val title: String,
    val value: Double,
    val unit: String
)
data class DaySummary(
    val totalWater: Double,
    val averagePulse: Double,
    val lastSleep: Double
)
fun List<HealthRecord>.summary(): DaySummary {
    val totalWater = filter { it.title == "Water" }
        .sumOf { it.value }

    val pulses = filter { it.title == "Pulse" }
    val averagePulse = if (pulses.isNotEmpty()) {
        pulses.map { it.value }.average()
    } else {
        0.0
    }

    val lastSleep = lastOrNull { it.title == "Sleep" }?.value ?: 0.0

    return DaySummary(
        totalWater = totalWater,
        averagePulse = averagePulse,
        lastSleep = lastSleep
    )
}

fun main() {
    val records = listOf(
        HealthRecord(1, "Water", 500.0, "мл"),
        HealthRecord(2, "Pulse", 72.0, "уд/хв"),
        HealthRecord(3, "Water", 700.0, "мл"),
        HealthRecord(4, "Pulse", 80.0, "уд/хв"),
        HealthRecord(5, "Sleep", 7.5, "год"),
        HealthRecord(6, "Sleep", 8.0, "год")
    )

    val result = records.summary()
    println("Sleep quality tests:")
    println("5 hours: ${sleepQuality(5.0)}")
    println("7 hours: ${sleepQuality(7.0)}")
    println("10 hours: ${sleepQuality(10.0)}")

    println("Daily water: ${result.totalWater} ml")
    println("Avg pulse: ${result.averagePulse}")
    println("Last sleep: ${result.lastSleep} hours")
}